void heapify(int a[], int n, int i) {
    int lg = i, l = 2 * i + 1, r = 2 * i + 2;
    if (l < n && a[l] > a[lg]) lg = l;
    if (r < n && a[r] > a[lg]) lg = r;
    if (lg != i) {
        int tmp = a[i];
        a[i] = a[lg];
        a[lg] = tmp;
        heapify(a, n, lg);
    }
}

void heapSort(int a[], int n) {
    for (int i = n / 2 - 1; i >= 0; i--) heapify(a, n, i);
    for (int i = n - 1; i > 0; i--) {
        int t = a[0];
        a[0] = a[i];
        a[i] = t;
        heapify(a, i, 0);
    }
}

